import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        final int MOD = 998244353;
        int n = in.nextInt();
        int k = in.nextInt();
        int[] basePoly = new int[10];
        for (int i = 0; i < k; i++) {
            basePoly[in.nextInt()] = 1;
        }

        int[] resultPoly = new int[]{1};
        int power = n / 2;
        while (power > 0) {
            if ((power & 1) == 1) {
                resultPoly = multiply(resultPoly, basePoly, MOD);
            }
            basePoly = multiply(basePoly, basePoly, MOD);
            power >>= 1;
        }

        long total = 0;
        for (int coeff : resultPoly) {
            total = (total + (long)coeff * coeff) % MOD;
        }
        out.println(total);
        out.close();
    }

    static int[] multiply(int[] p1, int[] p2, int mod) {
        int len1 = p1.length, len2 = p2.length;
        int resultLen = len1 + len2 - 1;
        int fftSize = 1;
        while (fftSize < resultLen) fftSize <<= 1;

        double[] re1 = new double[fftSize];
        double[] im1 = new double[fftSize];
        double[] re2 = new double[fftSize];
        double[] im2 = new double[fftSize];

        for (int i = 0; i < len1; i++) {
            long val = ((long)p1[i] % mod + mod) % mod;
            re1[i] = val & 0x7fff;
            im1[i] = val >>> 15;
        }
        for (int i = 0; i < len2; i++) {
            long val = ((long)p2[i] % mod + mod) % mod;
            re2[i] = val & 0x7fff;
            im2[i] = val >>> 15;
        }

        fft(re1, im1, false);
        fft(re2, im2, false);

        double[] prodRe = new double[fftSize];
        double[] prodIm = new double[fftSize];
        double[] extraRe = new double[fftSize];
        double[] extraIm = new double[fftSize];

        double scale = 0.25 / fftSize;
        for (int i = 0; i < fftSize; i++) {
            int j = (fftSize - i) & (fftSize - 1);

            double a1r = (re1[i] + re1[j]) * 0.5;
            double a1i = (im1[i] - im1[j]) * 0.5;
            double a2r = (im1[i] + im1[j]) * 0.5;
            double a2i = (re1[j] - re1[i]) * 0.5;

            double b1r = (re2[i] + re2[j]) * 0.5;
            double b1i = (im2[i] - im2[j]) * 0.5;
            double b2r = (im2[i] + im2[j]) * 0.5;
            double b2i = (re2[j] - re2[i]) * 0.5;

            prodRe[i] = a1r * b1r - a1i * b1i - a2r * b2i - a2i * b2r;
            prodIm[i] = a1r * b1i + a1i * b1r + a2r * b2r - a2i * b2i;
            extraRe[i] = a1r * b2r - a1i * b2i + a2r * b1r - a2i * b1i;
            extraIm[i] = a1r * b2i + a1i * b2r + a2r * b1i + a2i * b1r;
        }

        fft(prodRe, prodIm, true);
        fft(extraRe, extraIm, true);

        int[] output = new int[resultLen];
        for (int i = 0; i < resultLen; i++) {
            long part1 = Math.round(prodRe[i]);
            long part2 = Math.round(extraRe[i]);
            long part3 = Math.round(prodIm[i]);
            output[i] = (int)((part1 + ((part2 % mod) << 15) + ((part3 % mod) << 30)) % mod);
        }
        return output;
    }

    static void fft(double[] re, double[] im, boolean inverse) {
        int n = re.length;
        int bits = 32 - Integer.numberOfLeadingZeros(n);
        for (int i = 1; i < n; i++) {
            int j = Integer.reverse(i) >>> (32 - bits);
            if (i < j) {
                double temp = re[i]; re[i] = re[j]; re[j] = temp;
                temp = im[i]; im[i] = im[j]; im[j] = temp;
            }
        }

        for (int len = 2; len <= n; len <<= 1) {
            int half = len >> 1;
            double[] cosines = new double[half];
            double[] sines = new double[half];
            double angle = 2 * Math.PI / len * (inverse ? -1 : 1);
            for (int i = 0; i < half; i++) {
                cosines[i] = Math.cos(i * angle);
                sines[i] = Math.sin(i * angle);
            }

            for (int i = 0; i < n; i += len) {
                for (int j = 0; j < half; j++) {
                    double cr = cosines[j];
                    double ci = sines[j];
                    double ur = re[i + j];
                    double ui = im[i + j];
                    double vr = re[i + j + half] * cr - im[i + j + half] * ci;
                    double vi = re[i + j + half] * ci + im[i + j + half] * cr;

                    re[i + j] = ur + vr;
                    im[i + j] = ui + vi;
                    re[i + j + half] = ur - vr;
                    im[i + j + half] = ui - vi;
                }
            }
        }

        if (inverse) {
            for (int i = 0; i < n; i++) {
                re[i] /= n;
                im[i] /= n;
            }
        }
    }

    static class InputReader {
        private final InputStream inStream;
        private final byte[] buffer = new byte[1024];
        private int ptr, length;

        public InputReader(InputStream inStream) { this.inStream = inStream; }

        private int nextByte() {
            if (length == -1) throw new RuntimeException();
            if (ptr >= length) {
                ptr = 0;
                try { length = inStream.read(buffer); } catch (IOException e) { throw new RuntimeException(); }
                if (length <= 0) return -1;
            }
            return buffer[ptr++] & 0xff;
        }

        public int nextInt() {
            int c;
            while ((c = nextByte()) <= ' ') if (c == -1) throw new RuntimeException();
            int sign = 1;
            if (c == '-') { sign = -1; c = nextByte(); }
            int value = 0;
            do {
                if (c < '0' || c > '9') throw new RuntimeException();
                value = value * 10 + c - '0';
                c = nextByte();
            } while (c > ' ');
            return value * sign;
        }
    }
}
